 const navigate=useCallback((v:string)=>{setView(v);setSearch('');setPage(0);const keep=v==='plan-atividade'?new URLSearchParams(location.search).get('plano'):null;const url=v==='painel'?'/':`/?modulo=${v}${keep?'&plano='+encodeURIComponent(keep):''}`;if(location.pathname+location.search!==url)history.pushState(null,'',url);window.scrollTo({top:0})},[]);
